mapper.select:
select node_id as nodeId, site_id as sietId, operation_type as operationType, operation_details as operationDetails, created_user as createUser, created_time as createTime, node_type as nodeType, site_x as siteX, site_y as siteY, site_z as siteZ, created_user as createdUser, created_time as createdTime, gather_site as gatherSite from tb_node_operation_history
and node_id = #{nodeOperationDto.nodeId}
order by created_time desc
